package com.weaponsregistration.transfer.controller;import com.weaponsregistration.transfer.dto.TransferContract.*;import com.weaponsregistration.transfer.service.TransferService;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/erp/transfers")public class TransferController{private final TransferService service;public TransferController(TransferService service){this.service=service;}@GetMapping("/stock")public Page<StockOption>stock(@RequestParam long organizationId,@RequestParam long sourceUnitId,@RequestParam String kind,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="0")int page){return service.stock(organizationId,sourceUnitId,kind,search,page);}@PostMapping public TransferView finalize(@RequestBody FinalizeRequest r){return service.finalize(r);}@GetMapping public Page<TransferView>list(@RequestParam long organizationId,@RequestParam(required=false)Long unitId,@RequestParam(defaultValue="0")int page){return service.list(organizationId,unitId,page);}@GetMapping("/{id}")public TransferView get(@PathVariable long id){return service.get(id);}}
